INSERT OR REPLACE INTO books (id, slug, title, subtitle, short_description, description, author_id, author_name, author_role, co_author, publisher, publication_date, publication_year, edition, language, pages, isbn, isbn10, isbn13, sku, category, category_slug, tags, price, original_price, discount_percent, currency, show_original_price, show_discount_badge, in_stock, stock_count, stock_status, track_inventory, low_stock_threshold, status, is_featured, is_primary_featured, is_bestseller, is_new_release, badge, formats, cover_image, back_cover_image, spine_image, mockup_3d_image, gallery_images, preview_images, sample_pages, pdf_sample_url, ebook_download_url, purchase_links, about_book, what_you_will_learn, table_of_contents, weight, dimensions, meta_title, meta_description, canonical_url, focus_keyword, og_title, og_description, og_image, no_index, rating, review_count, views_count, clicks_count, purchases_count, frequently_bought_with_id, seller, fulfilled_by, delivery, replacement, payment, category_breadcrumb, google_enabled, google_excluded, google_offer_id, google_product_resource_name, google_data_source_name, google_last_synced_at, google_sync_status, google_issue_count, google_issues, google_target_country, google_content_language, google_feed_label, google_product_category, google_product_type, google_custom_label_0, google_custom_label_1, google_custom_label_2, google_condition, google_availability, google_mpn, created_at, updated_at, published_at) VALUES ('book-2', 'dear-son-life-lessons-from-a-father', 'Dear Son : Life Lessons from a Father', 'Life Lessons for Young Adults Entering Adulthood', NULL, 'A heartfelt collection of life lessons from a father to his son, helping young adults navigate adulthood, goals, money, values, character, health, responsibility and personal growth.', 'author-sandeep-sahni', 'Sandeep Sahni', 'Founder & Managing Director, Sahayak Associates', NULL, 'Notion Press', '29 April 2021', 2021, '1st Edition', 'English', 294, '9781637815279', NULL, '9781637815279', 'SB-DEAR-SON', 'Family & Relationships / Personal Development', 'family-relationships', '["Young Adults","Personal Development","Life Lessons","Family","Father and Son","Notion Press"]', 359, 399, 10, 'INR', 1, 1, 1, 42, NULL, 1, 5, 'published', 1, 0, 1, 1, NULL, '["Paperback"]', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-192900-2522ea.png', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-192918-3d9c60.png', NULL, NULL, '["https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-192900-2522ea.png"]', NULL, '[{"pageNumber":1,"chapterTitle":"Chapter 1: Stepping Into the Real World","title":"The Great Transition","content":["To my son, as you stand on the precipice of adulthood, the world before you holds immense promise and challenge.","These lessons are compiled to serve as an anchor for your decisions, a guide for your financial awareness, and a reminder of the character that defines true success."]}]', NULL, NULL, NULL, '["A heartfelt collection of life lessons from a father to his son, helping young adults navigate adulthood, goals, money, values, character, health, responsibility and personal growth.","Written by Sandeep Sahni, this book is designed as a special message from a father to his child, sharing practical guidance and insights to help the next generation step into adulthood with clarity and strength."]', '["21 chapters","Practical guidance for young adults","Life lessons from a father''s experience","Covers dreams and goals","Money and financial awareness","Values and character","Health and personal development","Upskilling and career growth","Responsibility and decision-making","Suitable for young adults and parents"]', '[{"chapter":1,"title":"Stepping Into the Real World","pages":"1 - 25"},{"chapter":2,"title":"Dreams, Goals, and Ambitions","pages":"26 - 55"},{"chapter":3,"title":"Understanding Financial Acumen","pages":"56 - 90"},{"chapter":4,"title":"Constructing Character & Values","pages":"91 - 140"},{"chapter":5,"title":"Health, Wellness, and Mental Fortitude","pages":"141 - 190"},{"chapter":6,"title":"Decision Making and Adult Responsibility","pages":"191 - 294"}]', '340 grams', '14.0 x 1.8 x 21.6 cm', 'Dear Son : Life Lessons from a Father by Sandeep Sahni | Sahayak Associates', 'Buy Dear Son : Life Lessons from a Father by Sandeep Sahni, a paperback featuring 21 chapters of heartfelt life lessons on goals, money, character, and personal growth.', NULL, NULL, NULL, NULL, NULL, 0, 4.4, 48, 0, 0, 0, 'book-1', NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-02T13:11:08.365Z', NULL);
