otion Press', 'September 2021', 2021, '1st Edition', 'English', 256, '9781637816509', NULL, '9781637816509', 'SB-MBA-MONEY', 'Business & Finance / Investments & Securities', 'business-finance', '["Investments","Finance","Personal Finance","Behavioral Economics","Money Management","Notion Press"]', 436, 499, 13, 'INR', 1, 1, 1, 65, NULL, 1, 5, 'published', 1, 0, 1, 1, NULL, '["Paperback"]', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-174938-52ff8d.png', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-174952-93262f.png', NULL, NULL, '["https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-174938-52ff8d.png"]', NULL, '[{"pageNumber":1,"chapterTitle":"Chapter 1: Understanding Your Money Beliefs","title":"The Emotion Behind the Balance Sheet","content":["Money is rarely just about numbers. It is an emotional landscape shaped by upbringing, societal expectations, and core internal drivers.","Before we can master compound interest or asset allocation, we must first understand the narratives we tell ourselves about wealth, risk, and security."]}]', NULL, NULL, NULL, '["How we think about money can be very different from how we feel about it. While financial concepts may appear simple on paper, budgeting, financial conversations, risk calculation, investment discipline and wealth preservation can often be challenging.","What My MBA Did Not Teach Me About Money presents practical strategies around money beliefs, financial challenges, stock market investing, personal biases and financial vulnerability.","The ideas are based on the authors’ practical experiences and their work advising clients, with the aim of bridging the gap between the emotional human perspective and the analytical financial perspective of money."]', '["Understand your money beliefs","Learn practical personal finance strategies","Navigate stock markets more effectively","Identify and overcome financial biases","Understand risk and reward","Improve budgeting and investment discipline","Manage financial vulnerability","Bridge emotional and logical approaches to money"]', '[{"chapter":1,"title":"Understanding Your Money Beliefs","pages":"1 - 32"},{"chapter":2,"title":"Practical Personal Finance Strategies","pages":"33 - 68"},{"chapter":3,"title":"Navigating Stock Markets Effectively","pages":"69 - 110"},{"chapter":4,"title":"Identifying and Overcoming Financial Biases","pages":"111 - 150"},{"chapter":5,"title":"Risk and Reward Dynamics","pages":"151 - 198"},{"chapter":6,"title":"Budgeting & Investment Discipline","pages":"199 - 256"}]', '320 grams', '14.0 x 1.6 x 21.5 cm', 'What My MBA Did Not Teach Me About Money | Sanjit Singh Paul & Sandeep Sahni', 'A profound exploration of money beliefs, investing, risk, and financial psychology. Buy the paperback edition by Sanjit Singh Paul & Sandeep Sahni.', NULL, NULL, NULL, NULL, NULL, 0, 4.6, 71, 0, 0, 0, 'book-1', 'Cocoblu Retail', 'Amazon', 'Free Delivery', '10 Days Replacement', 'Pay on Delivery / Secure Transaction', 'Books > Higher Education Textbooks > Business & Finance > Investments & Securities', 1, 0, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-02T13:11:55.354Z', NULL);
