es', NULL, 'Notion Press', 'September 2021', 2021, '1st Edition', 'English', 192, '9781637816516', NULL, '9781637816516', 'SB-INV-DICT', 'Business & Economics / Investments & Personal Finance', 'business-finance', '["SIP","Mutual Funds","Stocks","CAGR","XIRR","Personal Finance","Notion Press"]', 449, 499, 10, 'INR', 1, 1, 1, 110, NULL, 1, 5, 'published', 1, 0, 1, 1, NULL, '["Paperback"]', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-175140-8f7a50.png', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-175208-6c232d.png', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-175241-1e4445.png', NULL, '["https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-02-175140-8f7a50.png"]', NULL, '[{"pageNumber":1,"chapterTitle":"Chapter 1: Introduction to Personal Finance","title":"Demystifying the Language of Money","content":["Welcome to the Investment Dictionary. Finance is often shielded behind complex terminology, making it intimidating for beginners.","This dictionary bridges that gap, presenting terms like CAGR, SIP, and Yield in clear, everyday language with practical context."]}]', NULL, NULL, NULL, '["Investment Dictionary is a practical and beginner-friendly guide created to simplify the complex world of investments and personal finance.","The book explains commonly used financial terms and concepts in clear, easy-to-understand language, making it suitable for readers with little or no prior financial knowledge.","It covers essential topics such as SIP, Mutual Funds, Demat Accounts, CAGR, XIRR, ULIP, REIT, Alpha, Beta, Yield, Hedging and many other investment concepts.","Designed in a dictionary-style format, readers can quickly look up terms whenever they need clarity.","The book is useful for new investors, students, entrepreneurs, working professionals and anyone who wants to improve their financial literacy and build greater confidence in investment-related discussions."]', '["Beginner-friendly investment guide","Dictionary-style quick reference","SIP explained","Mutual Funds explained","Stocks and market concepts","CAGR and XIRR","Demat Accounts","ULIP and REIT","Alpha and Beta","Yield and Hedging","Personal finance terminology","Suitable for students, investors and professionals"]', '[{"chapter":1,"title":"Introduction to Personal Finance & Dictionary Format","pages":"1 - 15"},{"chapter":2,"title":"Core Investment Vehicles (SIP, Mutual Funds, Demat Accounts)","pages":"16 - 55"},{"chapter":3,"title":"Key Financial Metrics (CAGR, XIRR, Yield)","pages":"56 - 90"},{"chapter":4,"title":"Advanced Market Concepts (REIT, Alpha, Beta, Hedging)","pages":"91 - 145"},{"chapter":5,"title":"A-to-Z Glossary of Terms","pages":"146 - 192"}]', '240 grams', '14.0 x 1.2 x 21.5 cm', 'Investment Dictionary by Sandeep Sahni | SIP, Mutual Funds, Stocks, CAGR & XIRR', 'Buy Investment Dictionary by Sandeep Sahni, a beginner-friendly guide explaining SIP, Mutual Funds, Stocks, CAGR, XIRR, Demat Accounts, REIT, Alpha, Beta, Yield, Hedging and other important investment concepts.', NULL, NULL, NULL, NULL, NULL, 0, 5, 1, 0, 0, 0, 'book-1', 'SAHAYAK ASSOCIATES', 'Amazon', 'Free Delivery', '10 Days Replacement', 'Secure Transaction', 'Books > Business & Economics > Analysis & Strategy', 1, 0, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-02T13:12:53.474Z', NULL);
INSERT OR REPLACE INTO books (id, slug, title, subtitle, short_description, description, author_id, author_name, author_role, co_author, publisher, publication_date, publication_year, edition, language, pages, isbn, isbn10, isbn13, sku, category, category_slug, tags, price, original_price, discount_percent, currency, show_original_price, show_discount_badge, in_stock, stock_count, stock_status, track_inventory, low_stock_threshold, status, is_featured, is_primary_featured, is_bestseller, is_new_release, badge, formats, cover_image, back_cover_image, spine_image, mockup_3d_image, gallery_images, preview_images, sample_pages, pdf_sample_url, ebook_download_url, purchase_links, about_book, what_you_will_learn, table_of_contents, weight, dimensions, meta_title, meta_description, canonical_url, focus_keyword, og_title, og_description, og_image, no_index, rating, review_count, views_count, clicks_count, purchases_count, frequently_bought_with_id, seller, fulfilled_by, delivery, replacement, payment, category_breadcrumb, google_enabled, google_excluded, google_offer_id, google_product_resource_name, google_data_source_name, google_last_synced_at, google_sync_status, google_issue_count, google_issues, google_target_country, google_content_language, google_feed_label, google_product_category, google_product_type, google_custom_label_0, google_custom_label_1, google_custom_label_2, google_condition, google_availability, google_mpn, created_at, updated_at, published_at) VALUES ('book-1', 'heyy-18-what-an-18-year-old-should-know', 'Heyy 18: What an 18 Year Old Should Know', '52 Practical Life Lessons for Young Adults', NULL, 'Turning 18 is the beginning of a new chapter — a step into adulthood filled with greater freedom, new responsibilities, important choices and life-changing experiences.

“Heyy 18: What an 18 Year Old Should Know” brings together 52 practical life lessons designed to guide young adults through one of the most important stages of life.

Written as a special message from a father to his child, the book explores essential ideas around character, discipline, relationships, responsibility, decision-making and personal growth.

Thoughtful, relatable and easy to read, the book encourages young readers to reflect on their values, understand their choices and approach adulthood with greater confidence, wisdom and purpose.', 'author-sandeep-sahni', 'Sandeep Sahni', 'Founder & Managing Director, Sahayak Associates', NULL, 'Sahayak Associates', 'September 2026', 2026, '1st Hardcover Edition', 'English', 240, '9789385500589', '9385500589', '9789385500589', 'SB-HEYY-18', 'Young Adults', 'young-adults', '["Young Adults","Personal Development","Life Lessons","Self Improvement","18 Year Old","Student Books","Gift Books","Sandeep Sahni"]', 399, 499, 20, 'INR', 1, 1, 1, 95, 'In Stock', 1, 5, 'published', 1, 0, 1, 0, 'Featured', '["Paperback","eBook"]', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-190232-b18b97.png', 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-190217-1dc4de.png', NULL, 'https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-190232-b18b97.png', '["https://pub-d7c01d3edc7e4dbab0acb59d64c988a8.r2.dev/sahayak/books/20260902-screenshot-2026-09-01-190232-b18b97.png"]', NULL, '[{"pageNumber":1,"chapterTitle":"Chapter 1: Stepping Into Adulthood","title":"A Father’s Message","content":["Turning eighteen is not just a birthday; it is the opening of a profound new gateway.","With greater freedom comes the subtle but heavy responsibility of constructing your own character.","This book contains fifty-two practical reflections, one for each week of your transition, to anchor your choices in integrity and clear wisdom."]}]', NULL, NULL, NULL, '["Young adults turning 18","Students entering a new stage of life","Parents looking for a meaningful gift","Grandparents looking for a gift for young adults","Readers interested in personal development","Anyone beginning a journey toward independence and responsibility"]', '["52 practical life lessons","Personal growth and self-development","Character and discipline","Relationships","Responsibility","Decision-making","Preparing young adults for adulthood","Meaningful gift for an 18-year-old"]', '[{"chapter":1,"title":"Introduction: Stepping Into Adulthood","pages":"1 - 15"},{"chapter":2,"title":"The 52 Essential Life Lessons","pages":"16 - 150"},{"chapter":3,"title":"Action Guide for Personal Growth","pages":"151 - 180"}]', NULL, NULL, 'Heyy 18: What an 18 Year Old Should Know by Sandeep Sahni | Sahayak Associates', 'Buy Heyy 18: What an 18 Year Old Should Know by Sandeep Sahni, a paperback featuring 52 practical life lessons for young adults covering responsibility, relationships, discipline, decision-making and personal growth.', NULL, 'Heyy 18 book', NULL, NULL, NULL, 0, 4.8, 94, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-02T13:12:22.696Z', NULL);

