-- --- BLOGS ---
INSERT OR REPLACE INTO blogs (id, slug, title, excerpt, content, category, tags, author, author_role, author_avatar, publish_date, read_time, featured_image, status, seo_title, meta_description, created_at, updated_at) VALUES ('blog-1', 'the-future-of-constitutional-jurisprudence-in-the-ai-era', 'The Future of Constitutional Jurisprudence in the AI Era', 'How algorithms and predictive decision systems are challenging foundational principles of natural justice and administrative transparency.', '["As machine intelligence penetrates judicial drafting, credit scoring, and municipal resource allocation, the bedrock legal doctrine of Audi Alteram Partem (listen to the other side) faces an unprecedented test.","When an opaque neural network generates a determination affecting citizen liberty or corporate licensing, who bears the burden of explainability? Our latest research at Sahayak Associates establishes three critical legal standards for algorithmic accountability.","First, no administrative order may be enforced without human supervisory sign-off. Second, the training data provenance must be accessible during judicial review. Third, algorithmic bias audits must be made mandatory across public governance portfolios."]', 'Law & Jurisprudence', '["AI Law","Constitutional Rights","Legal Ethics","Sahayak Research"]', 'Adv. Meenakshi Sundaram', 'Senior Advocate & Legal Scholar', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=200&q=80', 'February 14, 2026', '6 min read', 'https://images.unsplash.com/photo-1589829545856-d10d557cf95f?auto=format&fit=crop&w=1200&q=80', 'published', 'Constitutional Jurisprudence in the AI Era | Sahayak Books', 'Explore the intersection of machine learning and constitutional rights by Adv. Meenakshi Sundaram.', 'February 14, 2026', 'February 14, 2026');
INSERT OR REPLACE INTO blogs (id, slug, title, excerpt, content, category, tags, author, author_role, author_avatar, publish_date, read_time, featured_image, status, seo_title, meta_description, created_at, updated_at) VALUES ('blog-2', 'deconstructing-monetary-policy-transmission-in-emerging-markets', 'Deconstructing Monetary Policy Transmission in Emerging Markets', 'An empirical analysis of how repo rate adjustments influence commercial lending rates and capital investment velocity.', '["The conventional textbook view assumes an instant pass-through from central bank policy rates to commercial banking loan books. In reality, structural liquidity friction, statutory liquidity ratios, and asset-liability mismatches create substantial transmission lag.","In this detailed commentary, Dr. Rajeshwar Sen examines why traditional fiscal levers behave differently in emerging economic corridors and how corporate treasuries can hedge interest rate volatility proactively."]', 'Finance & Economics', '["Macroeconomics","Monetary Policy","Banking","Capital Markets"]', 'Dr. Rajeshwar Sen', 'Chief Economist, Sahayak Research', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80', 'January 30, 2026', '8 min read', 'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1200&q=80', 'published', 'Monetary Policy Transmission in Emerging Markets | Sahayak Insights', 'Dr. Rajeshwar Sen on central banking transmission and macro volatility.', 'January 30, 2026', 'January 30, 2026');
INSERT OR REPLACE INTO blogs (id, slug, title, excerpt, content, category, tags, author, author_role, author_avatar, publish_date, read_time, featured_image, status, seo_title, meta_description, created_at, updated_at) VALUES ('blog-3', 'mastering-the-art-of-high-stakes-negotiation-and-calm-authority', 'Mastering the Art of High-Stakes Negotiation & Calm Authority', 'Why the most powerful negotiator in the room is often the one who speaks least, listens deeply, and controls internal arousal levels.', '["Negotiation is fundamentally an exercise in emotional regulation. When billions of rupees or key policy covenants hang in the balance, amateur negotiators rely on aggressive rhetoric or artificial urgency.","Master negotiators, by contrast, practice the art of strategic silence, precision paraphrasing, and asymmetrical value concession. Learn the 4-phase preparation framework taught at Sahayak Associates Executive Retreats."]', 'Leadership & Governance', '["Negotiation","Executive Presence","Leadership","Mindset"]', 'Priya Malhotra', 'Behavioral Scientist & Executive Coach', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=200&q=80', 'January 18, 2026', '5 min read', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=1200&q=80', 'published', 'Mastering High-Stakes Negotiation | Sahayak Books', 'Executive coach Priya Malhotra on calmness, authority, and negotiation mastery.', 'January 18, 2026', 'January 18, 2026');

-- --- REVIEWS ---
INSERT OR REPLACE INTO reviews (id, book_id, book_title, user_name, user_avatar, rating, title, comment, date, verified_purchase, approved, status, sentiment, featured) VALUES ('rev-1', 'book-1', 'The Art of Strategic Governance', 'Rajeev Chandrashekhar, IAS', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80', 5, 'A landmark book for every civil servant in India', 'Dr. Sahayak has written what will certainly become the gold-standard reference for administrative governance. The chapters on crisis command and institutional audit are breathtakingly practical and ethically grounded.', 'February 12, 2026', 1, 1, 'Pending', NULL, 1);
INSERT OR REPLACE INTO reviews (id, book_id, book_title, user_name, user_avatar, rating, title, comment, date, verified_purchase, approved, status, sentiment, featured) VALUES ('rev-2', 'book-1', 'The Art of Strategic Governance', 'Prof. Suniti Deshmukh', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=200&q=80', 5, 'Impeccable academic rigor combined with real-world wisdom', 'We have already adopted this text into our Master of Public Policy syllabus at the National Law School. The book quality, hardcover binding, and gold foil typography make it a joy to own.', 'January 28, 2026', 1, 1, 'Pending', NULL, 1);
INSERT OR REPLACE INTO reviews (id, book_id, book_title, user_name, user_avatar, rating, title, comment, date, verified_purchase, approved, status, sentiment, featured) VALUES ('rev-3', 'book-2', 'Dear Son : Life Lessons from a Father', 'Karan Malhotra', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80', 5, 'Incredibly touching and deeply practical', 'This book has been a guiding light for my journey into adulthood. The lessons on financial awareness, goals, and values are written so beautifully and practically.', 'May 15, 2021', 1, 1, 'Pending', NULL, 1);
INSERT OR REPLACE INTO reviews (id, book_id, book_title, user_name, user_avatar, rating, title, comment, date, verified_purchase, approved, status, sentiment, featured) VALUES ('rev-4', 'book-4', 'Investment Dictionary', 'Anjali Gupta (MBA Student)', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80', 5, 'The easiest guide to understand financial jargon!', 'As a business student, CAGR and XIRR used to confuse me on spreadsheets. This dictionary explains them with amazing simplicity. A must-have desk reference!', 'December 4, 2021', 1, 1, 'Pending', NULL, 1);
INSERT OR REPLACE INTO reviews (id, book_id, book_title, user_name, user_avatar, rating, title, comment, date, verified_purchase, approved, status, sentiment, featured) VALUES ('rev-5', 'book-3', 'What My MBA Did Not Teach Me About Money', 'Siddharth Mukherjee (Wealth Consultant)', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=200&q=80', 5, 'Exceptional blend of behavioral psychology and practical finance', 'Sanjit Singh Paul and Sandeep Sahni provide unmatched clarity on how money beliefs govern our investing decisions. Essential reading for anyone who wants to conquer their financial biases.', 'October 12, 2021', 1, 1, 'Pending', NULL, 1);

